\set ON_ERROR_STOP on
begin;
create function pg_temp.assert_true(value boolean,message text) returns void language plpgsql as $$ begin if value is distinct from true then raise exception 'Assertion failed: %',message; end if; end $$;
create function pg_temp.fails(statement text) returns boolean language plpgsql as $$ begin execute statement; return false; exception when others then return true; end $$;
insert into auth.users(id) select ('00000000-0000-0000-0000-'||lpad(i::text,12,'0'))::uuid from generate_series(101,111) i;
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000101',true);
select public.command('save_profile','{"name":"Hippo"}',gen_random_uuid());
select pg_temp.assert_true((select username='hippo' from public.profiles where id=auth.uid()),'first Hippo receives hippo');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000102',true);
select public.command('save_profile','{"name":"  HIPPO!  "}',gen_random_uuid());
select pg_temp.assert_true((select username='hippo2' from public.profiles where id=auth.uid()),'duplicate and mixed-case display name receives hippo2');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000103',true);
select public.command('save_profile','{"name":"Hippo"}',gen_random_uuid());
select pg_temp.assert_true((select username='hippo3' from public.profiles where id=auth.uid()),'third Hippo receives hippo3');
select public.command('set_username','{"username":"river_hippo"}',gen_random_uuid());
select public.command('save_profile','{"name":"Renamed Person"}',gen_random_uuid());
select pg_temp.assert_true((select username='river_hippo' from public.profiles where id=auth.uid()),'explicit username survives old-client profile upserts and display-name edits');
select pg_temp.assert_true(pg_temp.fails($q$select public.command('set_username','{"username":"HIPPO"}',gen_random_uuid())$q$),'manual edits cannot claim a taken username with different case');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000101',true);
select public.command('save_profile','{"name":"Name Changed"}',gen_random_uuid());
select pg_temp.assert_true((select username='hippo' from public.profiles where id=auth.uid()),'automatic username remains stable on a display-name edit');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000104',true);
select public.command('save_profile','{"name":" José Núñez "}',gen_random_uuid());
select pg_temp.assert_true((select username='jose_nunez' from public.profiles where id=auth.uid()),'accented names and spaces normalize to a readable username');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000105',true);
select public.command('save_profile','{"name":"Li"}',gen_random_uuid());
select pg_temp.assert_true((select username='li1' from public.profiles where id=auth.uid()),'short names satisfy the existing minimum length');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000106',true);
select public.command('save_profile',jsonb_build_object('name',repeat('A',120)),gen_random_uuid());
select pg_temp.assert_true((select username=repeat('a',40) from public.profiles where id=auth.uid()),'long names fit the username length limit');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000107',true);
select public.command('save_profile',jsonb_build_object('name',repeat('A',120)),gen_random_uuid());
select pg_temp.assert_true((select username=repeat('a',39)||'2' from public.profiles where id=auth.uid()),'collision suffix stays inside the length limit');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000108',true);
select public.command('save_profile','{"name":"猴子"}',gen_random_uuid());
select pg_temp.assert_true((select username='member' from public.profiles where id=auth.uid()),'names without Latin letters receive a short editable fallback');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000109',true);
select public.command('save_profile','{"name":"!!!"}',gen_random_uuid());
select pg_temp.assert_true((select username='member2' from public.profiles where id=auth.uid()),'fallback usernames also stay unique');
select pg_temp.assert_true(not has_function_privilege('authenticated','public.default_username()','execute'),'automatic allocation is not an app RPC');
select pg_temp.assert_true(not has_function_privilege('anon','public.default_username()','execute'),'automatic allocation is not an anonymous RPC');
reset role;
-- Explicitly chosen handles are reserved before subsequent automatic allocation.
insert into public.profiles(id,name,username) values('00000000-0000-0000-0000-000000000110','Custom','otter');
insert into public.profiles(id,name) values('00000000-0000-0000-0000-000000000111','Otter');
select pg_temp.assert_true((select username='otter2' from public.profiles where name='Otter'),'manual handles are respected by automatic allocation');
select pg_temp.assert_true((select count(*)=count(distinct lower(username)) from public.profiles),'every handle remains unique across the entire database');
rollback;
